\draw[thick,black] (0,0)--(12,0)--(7,6)--(0,6)--cycle;
\draw[black] (0,0.4)--(0.4,0.4)--(0.4,0);
\node[below] at (6,0) {$12\text{ m}$};
\node[above] at (3.5,6) {$7\text{ m}$};
\node[left] at (0,3) {$6\text{ m}$};
